import{_ as e,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"List Transactions (Datagrid)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-transactions-list-gql","title":"List Transactions (Datagrid)","description":"Cursor-paginated transactions datagrid. Every transaction column plus the raw gateway data blob and the linked order summary is populated on each row.","query":"query AdminTransactions($first: Int, $after: String, $status: String) {\\n  adminTransactions(first: $first, after: $after, status: $status) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        transactionId\\n        invoiceId\\n        orderId\\n        orderIncrementId\\n        amount\\n        formattedAmount\\n        status\\n        type\\n        paymentMethod\\n        paymentTitle\\n        data\\n        createdAt\\n        updatedAt\\n        order\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      endCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"status\\": \\"paid\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminTransactions\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/transactions/4\\",\\n            \\"_id\\": 4,\\n            \\"transactionId\\": \\"pi_3PqXyz9aBcD\\",\\n            \\"invoiceId\\": 12,\\n            \\"orderId\\": 8,\\n            \\"orderIncrementId\\": \\"00000000008\\",\\n            \\"amount\\": 99.99,\\n            \\"formattedAmount\\": \\"$99.99\\",\\n            \\"status\\": \\"paid\\",\\n            \\"type\\": \\"capture\\",\\n            \\"paymentMethod\\": \\"cashondelivery\\",\\n            \\"paymentTitle\\": \\"Cash On Delivery\\",\\n            \\"data\\": { \\"gateway\\": \\"offline\\", \\"captured\\": true },\\n            \\"createdAt\\": \\"2026-05-20 12:35:00\\",\\n            \\"updatedAt\\": \\"2026-05-20 12:35:00\\",\\n            \\"order\\": {\\n              \\"id\\": 8,\\n              \\"incrementId\\": \\"00000000008\\",\\n              \\"status\\": \\"processing\\",\\n              \\"customerName\\": \\"John Doe\\",\\n              \\"customerEmail\\": \\"john.doe@example.com\\",\\n              \\"grandTotal\\": 99.99,\\n              \\"orderCurrencyCode\\": \\"USD\\"\\n            }\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"endCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/transactions/list.md","filePath":"api/graphql-api/admin/sales/transactions/list.md","lastUpdated":1786429091000}'),n={name:"api/graphql-api/admin/sales/transactions/list.md"};function r(s,t,c,i,l,m){return d(),a("div",null,t[0]||(t[0]=[o('<h1 id="list-transactions-datagrid" tabindex="-1">List Transactions (Datagrid) <a class="header-anchor" href="#list-transactions-datagrid" aria-label="Permalink to &quot;List Transactions (Datagrid)&quot;">​</a></h1><p>GraphQL counterpart of <code>GET /api/admin/transactions</code>. Returns a cursor-paginated list of payment transactions — the same rows shown on the admin <strong>Sales → Transactions</strong> datagrid. Every transaction <strong>column</strong> plus the raw gateway <code>data</code> blob and the linked <code>order</code> summary are populated on each row.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><p><code>adminTransactions(first, after, id, transaction_id, invoice_id, order_id, status, created_at_from, created_at_to, sort, order)</code> — a cursor <code>QueryCollection</code>. Every REST query parameter is also exposed as a GraphQL argument; see the <a href="/api/rest-api/admin/sales/transactions/list.html">REST page</a> for the full argument table.</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.transactions.view</code></p><div class="warning custom-block"><p class="custom-block-title">data and order are returned whole</p><p><code>data</code> (the gateway payload) and <code>order</code> (the order summary) are returned as JSON — <strong>query them bare, without a sub-selection</strong> (<code>data</code> / <code>order</code>, not <code>order { … }</code>). The whole object comes back. See the field reference below for the keys inside each.</p></div><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>Every field is populated on each row — the transaction columns, the resolved <code>paymentTitle</code>, the raw gateway <code>data</code> object, and the <code>order</code> summary.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>Resource IRI of the transaction (<code>/api/admin/transactions/{id}</code>).</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Transaction row id.</td></tr><tr><td><code>transactionId</code></td><td><code>String</code></td><td>Gateway transaction id.</td></tr><tr><td><code>invoiceId</code></td><td><code>Int</code></td><td>The invoice this transaction paid (if any).</td></tr><tr><td><code>orderId</code> / <code>orderIncrementId</code></td><td><code>Int</code> / <code>String</code></td><td>Parent order id and human-facing number.</td></tr><tr><td><code>amount</code> / <code>formattedAmount</code></td><td><code>Float</code> / <code>String</code></td><td>Transaction amount, raw and formatted.</td></tr><tr><td><code>status</code></td><td><code>String</code></td><td>Transaction status — e.g. <code>paid</code>, <code>pending</code>.</td></tr><tr><td><code>type</code></td><td><code>String</code></td><td>Transaction type — e.g. <code>capture</code>.</td></tr><tr><td><code>paymentMethod</code> / <code>paymentTitle</code></td><td><code>String</code></td><td>Payment method code and its human-readable title.</td></tr><tr><td><code>data</code></td><td>JSON</td><td>The verbatim gateway response payload — query bare; shape varies by gateway; may be <code>null</code>.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>String</code></td><td>Timestamps.</td></tr><tr><td><code>order</code></td><td>JSON</td><td>Slim order summary (query bare) — <code>id</code>, <code>incrementId</code>, <code>status</code>, <code>customerName</code>, <code>customerEmail</code>, <code>grandTotal</code>, <code>orderCurrencyCode</code>.</td></tr></tbody></table>',10)]))}const h=e(n,[["render",r]]);export{u as __pageData,h as default};
